INSERT INTO caballo (
  id, nombre, fecha_nacimiento, categoria, sexo, rol_reproductivo,
  raza_id, pelaje_id, numero_chip, numero_registro, sociedad_id, activo,
  padre_id, padre_nombre, madre_id, madre_nombre, domador, observaciones)
SELECT
  gen_random_uuid(), d.nombre, d.fecha, d.categoria, d.sexo, d.rol,
  10, d.pelaje_id, d.chip, d.rp, 'fc880764-c628-4961-92f9-527a0bf03d8f', d.activo,
  p.id, CASE WHEN p.id IS NULL THEN d.padre_libre END,
  m.id, CASE WHEN m.id IS NULL THEN d.madre_libre END,
  d.domador, d.obs
FROM datos d
LEFT JOIN LATERAL (
  SELECT c.id FROM caballo c
  WHERE c.sociedad_id = 'fc880764-c628-4961-92f9-527a0bf03d8f'
    AND lower(c.nombre) = lower(d.padre_match)
    AND c.categoria IN ('Caballo', 'Padrillo')
  ORDER BY c.created_at LIMIT 1
) p ON d.padre_match IS NOT NULL
LEFT JOIN LATERAL (
  SELECT c.id FROM caballo c
  WHERE c.sociedad_id = 'fc880764-c628-4961-92f9-527a0bf03d8f'
    AND lower(c.nombre) = lower(d.madre_match)
    AND c.categoria = 'Yegua'
  ORDER BY c.created_at LIMIT 1
) m ON d.madre_match IS NOT NULL;

END $$;
